<?php
namespace App\Http\Controllers;
use App\Domain\{DriverOnboarding,PayChanguTopups};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage,Crypt,RateLimiter};
use Illuminate\Support\Str;
class DriverSetupController extends Controller {
 public function __construct(private DriverOnboarding $onboarding,private PayChanguTopups $payments){}
 private function account(Request $r,array $roles=['rider','driver']):object{$a=DB::table('accounts')->find($r->session()->get('account_id'));abort_unless($a,401,'Please verify your phone number.');abort_unless(in_array($a->role,$roles),403);return $a;}
 private function driver(object $a):object{$d=DB::table('drivers')->where('account_id',$a->id)->first();abort_unless($d,403,'Save your driver details first.');return $d;}
 public function show(Request $r):array{$a=$this->account($r);$d=DB::table('drivers')->where('account_id',$a->id)->first();return $d?$this->onboarding->view($d):['profile'=>[],'documents'=>[],'document_kinds'=>DriverOnboarding::DOCUMENTS,'verification_checks'=>DriverOnboarding::CHECKS,'required_documents'=>$this->onboarding->required([]),'onboarding_state'=>'draft','starter_credit_offer_minor'=>(int)config('paychangu.driver_trial_credit_minor')];}
 public function save(Request $r):array{$a=$this->account($r);$v=$r->validate($this->onboarding->rules());$this->onboarding->save($a,$v);return $this->show($r);}
 public function submit(Request $r):array{$a=$this->account($r,['driver']);$this->onboarding->submit($this->driver($a)->id);return $this->show($r);}
 public function upload(Request $r):array{
  $a=$this->account($r,['driver']);$v=$r->validate(['kind'=>'required|in:'.implode(',',DriverOnboarding::DOCUMENTS),'document'=>'required|file|mimes:jpg,jpeg,png,pdf|max:5120']);
  if(in_array($v['kind'],['selfie','vehicle_front','vehicle_back','vehicle_interior']))$r->validate(['document'=>'image|mimes:jpg,jpeg,png|max:5120']);
  $path='driver-documents/'.Str::uuid().'.enc';$file=$r->file('document');abort_unless(Storage::disk('local')->put($path,Crypt::encryptString(base64_encode($file->getContent()))),503,'Document storage is unavailable.');
  $oldPath=null;try{DB::transaction(function()use($a,$v,$path,$file,&$oldPath){$d=DB::table('drivers')->where('account_id',$a->id)->lockForUpdate()->first();abort_unless($d && in_array($d->onboarding_state,['draft','rejected']),409,'Documents are locked while awaiting review.');$old=DB::table('driver_documents')->where(['driver_id'=>$d->id,'kind'=>$v['kind']])->first();DB::table('driver_documents')->updateOrInsert(['driver_id'=>$d->id,'kind'=>$v['kind']],['path'=>$path,'mime'=>$file->getMimeType(),'status'=>'pending','review_reason'=>null,'reviewed_by'=>null,'reviewed_at'=>null,'created_at'=>now(),'updated_at'=>now()]);$oldPath=$old?->path;},5);}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}if($oldPath)Storage::disk('local')->delete($oldPath);return $this->show($r);
 }
 public function inspect(Request $r,int $id):array{$this->account($r,['admin','reviewer']);$d=DB::table('drivers')->find($id);abort_unless($d,404);return $this->onboarding->view($d,true);}
 public function document(Request $r,int $id,int $document){$a=$this->account($r,['driver','admin','reviewer']);$d=DB::table('drivers')->find($id);abort_unless($d && ($a->role!=='driver' || $d->account_id===$a->id),403);$doc=DB::table('driver_documents')->where(['id'=>$document,'driver_id'=>$id])->first();abort_unless($doc && Storage::disk('local')->exists($doc->path),404);$bytes=base64_decode(Crypt::decryptString(Storage::disk('local')->get($doc->path)),true);return response($bytes,200,['Content-Type'=>$doc->mime,'Content-Disposition'=>'attachment; filename="'.$doc->kind.'.'.($doc->mime==='application/pdf'?'pdf':'jpg').'"','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function documentReview(Request $r,int $id,int $document):array{$a=$this->account($r,['admin','reviewer']);$v=$r->validate(['status'=>'required|in:accepted,rejected','reason'=>'required|string|min:5|max:1000']);DB::transaction(function()use($a,$v,$id,$document){$d=DB::table('drivers')->where('id',$id)->lockForUpdate()->first();abort_unless($d && $d->onboarding_state==='submitted',409,'Application is not awaiting review.');$doc=DB::table('driver_documents')->where(['id'=>$document,'driver_id'=>$id])->first();abort_unless($doc,404);DB::table('driver_documents')->where('id',$doc->id)->update(['status'=>$v['status'],'review_reason'=>$v['reason'],'reviewed_by'=>$a->id,'reviewed_at'=>now(),'updated_at'=>now()]);DB::table('audit_records')->insert(['actor_id'=>$a->id,'action'=>'driver_document_review','resource'=>(string)$doc->id,'reason'=>$v['reason'],'details'=>json_encode(['driver_id'=>$id,'kind'=>$doc->kind,'status'=>$v['status']])]);},5);return $this->inspect($r,$id);}
 public function review(Request $r,int $id):array{$a=$this->account($r,['admin','reviewer']);$v=$r->validate(['status'=>'required|in:approved,rejected,suspended','vehicle_approved'=>'required|boolean','reason'=>'required|string|min:5|max:1000','checks'=>'nullable|array','checks.*'=>'boolean']);$this->onboarding->review($id,$a,$v['status'],$v['vehicle_approved'],$v['reason'],$v['checks']??[]);return ['ok'=>true];}
 public function topups(Request $r):array{$d=$this->driver($this->account($r,['driver']));return ['enabled'=>$this->payments->ready(),'mode'=>config('paychangu.mode'),'minimum_minor'=>config('paychangu.minimum_minor'),'maximum_minor'=>config('paychangu.maximum_minor'),'topups'=>DB::table('driver_topups')->where('driver_id',$d->id)->latest()->limit(50)->get()->map(fn($t)=>$this->payments->view($t))];}
 public function createTopup(Request $r):array{$a=$this->account($r,['driver']);$d=$this->driver($a);$key='topup:'.$a->id;abort_if(RateLimiter::tooManyAttempts($key,10),429,'Too many top-up attempts.');RateLimiter::hit($key,60);$v=$r->validate(['amount_minor'=>'required|integer|min:'.config('paychangu.minimum_minor').'|max:'.config('paychangu.maximum_minor'),'request_key'=>'required|uuid']);return $this->payments->view($this->payments->create($d,$a,$v['amount_minor'],$v['request_key']));}
 public function verifyTopup(Request $r,string $id):array{$a=$this->account($r,['driver']);$rate='verify-topup:'.$a->id;abort_if(RateLimiter::tooManyAttempts($rate,30),429,'Too many payment checks.');RateLimiter::hit($rate,60);$t=DB::table('driver_topups')->find($id);abort_unless($t && $t->driver_id===$this->driver($a)->id,404);return $this->payments->view($this->payments->verify($t->tx_ref));}
 public function webhook(Request $r){$this->payments->webhook($r->getContent(),$r->header('Signature'));return response()->json(['ok'=>true]);}
 public function returned(){return redirect('/?payment_return=1');}
}
